  CONSTRAINT `ck_application_version_ck_application_version_no` CHECK ((`version_no` >= 1)),
  CONSTRAINT `ck_application_version_ck_application_version_status` CHECK ((`status` in (_utf8mb4'PUBLISHED',_utf8mb4'SUPERSEDED')))
