ype\": \"string\"}, \"device_id\": {\"type\": \"integer\", \"minimum\": 1}, \"description\": {\"type\": \"string\", \"minLength\": 1}, \"reported_fault_code\": {\"type\": [\"string\", \"null\"], \"maxLength\": 40}}, \"additionalProperties\": false}',1,'2026-11-01 08:08:23.171162');
