CREATE TABLE `tool_execution` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `execution_id` bigint NOT NULL,
  `tool_code` varchar(60) NOT NULL,
  `arguments` json DEFAULT NULL,
  `result` json DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `latency_ms` int NOT NULL,
  `trace_id` varchar(64) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_tool_execution_execution` (`execution_id`,`id`),
  CONSTRAINT `fk_tool_execution_execution_id_agent_execution` FOREIGN KEY (`execution_id`) REFERENCES `agent_execution` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_tool_execution_ck_tool_execution_status` CHECK ((`status` in (_utf8mb4'SUCCEEDED',_utf8mb4'FAILED',_utf8mb4'TIMEOUT')))
) ENGINE=InnoDB AUTO_INCREMENT=451 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
